#include <omp.h>
#include <vector>
#include <cstddef>

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) {
        return 0;
    }

    int max_degree = 0;
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(N);

    // Degree of a node is the sum of its row in the adjacency matrix.
    // This assumes a standard undirected adjacency matrix for a simple graph.
    #pragma omp parallel for default(none) shared(A, N, n) reduction(max:max_degree)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        int degree = 0;
        const size_t row_start = static_cast<size_t>(i) * N;

        for (size_t j = 0; j < N; ++j) {
            degree += A[row_start + j];
        }

        if (degree > max_degree) {
            max_degree = degree;
        }
    }

    return max_degree;
}
